    font-family:ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;
    color:var(--viz-text,#e8eaf0);
    -webkit-user-select:none;user-select:none;
  }
  .wrap{max-width:420px;margin:0 auto}
  .hud{
    display:flex;justify-content:space-between;gap:8px;
    font-size:11px;letter-spacing:.09em;text-transform:uppercase;
    color:var(--viz-muted,#98a0b3);margin-bottom:6px;
  }
  .hud b{color:var(--viz-text,#fff);font-size:14px;letter-spacing:0}
  .stage{
    position:relative;border-radius:14px;overflow:hidden;
    border:1px solid var(--viz-border,rgba(255,255,255,.14));
    background:var(--viz-panel,rgba(255,255,255,.04));
    box-shadow:inset 0 0 40px rgba(0,0,0,.25);
  }
  canvas{display:block;width:100%;aspect-ratio:360/260;touch-action:none;cursor:crosshair}
  .overlay{
    position:absolute;inset:0;display:none;flex-direction:column;
    align-items:center;justify-content:center;gap:8px;text-align:center;
    padding:16px;background:rgba(6,8,14,.72);backdrop-filter:blur(2px);
  }
  .overlay.on{display:flex}
  .big{font-size:18px;font-weight:650;letter-spacing:.01em}
  .sub{font-size:12.5px;color:var(--viz-muted,#9aa0b3)}
  button{
    margin-top:6px;border:0;border-radius:999px;cursor:pointer;
    padding:8px 18px;font-size:13px;font-weight:600;
    color:#fff;background:var(--viz-accent,#4f8cff);
    transition:transform .12s ease,filter .12s ease;
  }
  button:hover{filter:brightness(1.1)}
  button:active{transform:scale(.96)}
  .hint{margin-top:7px;text-align:center;font-size:11px;color:var(--viz-muted,#8d94a6)}
</style>

