    const rect = canvas.getBoundingClientRect();
    if (!rect.width) return;
    const scale = rect.width / W;
    canvas.width  = Math.round(W * scale * dpr);
    canvas.height = Math.round(H * scale * dpr);
    ctx.setTransform(scale*dpr, 0, 0, scale*dpr, 0, 0);
  }

